#!/bin/sh
# Package the expert-facing archive: the report, the tool sources, the organizer
# inputs, and the freshly rebuilt answer + audit trail.
#
#   ./scripts/package_expert_archive.sh [repo-root] [out-zip]
#
# Defaults: repo-root = two levels up from this script (the repository that
# holds tt-challenge/), out-zip = <repo-root>/dist/nsuhackaton-semarch-<commit>.zip.
#
# The archive is rebuilt from the working tree, never from a stale copy:
# `submission.json` and `report.json` are regenerated by the tool itself, so the
# report's numbers and the archived answer cannot drift apart. Build artifacts
# (`semarch/target/`) and the other teams' solutions (`NSU_HACK_ASU_TEAM/`) are
# never packaged.
set -eu

here=$(cd "$(dirname "$0")/.." && pwd)
root=${1:-"$(cd "$here/.." && pwd)"}
root=$(cd "$root" && pwd)

if [ ! -d "$root/tt-challenge/skeleton" ] || [ ! -d "$root/semarch/crates" ]; then
    echo "usage: $0 <repo-root with tt-challenge/ and semarch/> [out.zip]" >&2
    exit 2
fi

commit=$(git -C "$root" rev-parse --short HEAD 2>/dev/null || echo worktree)
out=${2:-"$root/dist/nsuhackaton-semarch-$commit.zip"}
mkdir -p "$(dirname "$out")"
out_dir=$(cd "$(dirname "$out")" && pwd)
out=$out_dir/$(basename "$out")

cd "$here"
cargo build --release -p semarch-cli

stage=$(mktemp -d)
trap 'rm -rf "$stage"' EXIT
name=nsuhackaton-semarch
mkdir -p "$stage/$name"

# The answer and its audit trail are rebuilt here, from the current sources.
./target/release/semarch tt-export "$root/tt-challenge" --out "$stage/$name/submission.json"
./target/release/semarch tt-report "$root/tt-challenge" --out "$stage/$name/report.json"

# The report and the initial plan, for comparison with what was built.
cp "$root/REPORT_FOR_EXPERT.md" "$root/PLAN_TRAIN_TICKET_ANALYZER.md" "$stage/$name/"

# Tool sources: no target/, no editor or macOS noise.
mkdir -p "$stage/$name/semarch"
(cd "$here" && tar -cf - \
    --exclude=target \
    Cargo.toml Cargo.lock README.md crates docs scripts) |
    (cd "$stage/$name/semarch" && tar -xf -)

# Organizer inputs, exactly as handed out (targets/ is the bulk of the size).
mkdir -p "$stage/$name/tt-challenge"
(cd "$root/tt-challenge" && tar -cf - \
    --exclude='__pycache__' \
    --exclude='.DS_Store' \
    .) | (cd "$stage/$name/tt-challenge" && tar -xf -)

# The organizer-provided sample of the submission format.
mkdir -p "$stage/$name/sample"
(cd "$root/sample" && tar -cf - \
    --exclude='__pycache__' \
    --exclude='.DS_Store' \
    .) | (cd "$stage/$name/sample" && tar -xf -)

rm -f "$out"
(cd "$stage" && zip -qr "$out" "$name")
echo "wrote $out"
echo "submission.json sha256: $(shasum -a 256 "$stage/$name/submission.json" | awk '{print $1}')"
